<?php

namespace App\Design\D2;

/**
 * The Design 2 @font-face rules, inlined in the page head by d2::layouts.app (with the CSP nonce) instead of being
 * bundled into app.css: their absolute /fonts/d2/… URLs then resolve against the page origin in production and
 * behind the Vite dev server (whose CSS lives on another origin that font-src 'self' blocks), they match the
 * preload links exactly, and the browser discovers the fonts before the stylesheet arrives. Source:
 * resources/css/d2/base/fonts.css, generated by scripts/fonts/fontsource-d2.mjs (contract:
 * docs/d2.1/phase-1/tokens.md §5).
 *
 * Groups. A browser requests every web font the laid-out text of the whole page needs in its first layout, also
 * for text far below the first screen (a language name in the footer, a sample document's watermark). groups()
 * splits the rules per locale so the first screen gets its faces first:
 *   base  the page language's interface faces (every weight and the Latin file of Arabic pages) and every
 *         metric-matched local fallback (with the space-only face of the Arabic families): active from the start;
 *   wide  faces the header shows from 768 px in another script (none since the approved language labels,
 *         brief §3.7; the group stays so the boot script's contract is unchanged);
 *   docs  the sample documents' faces (D2 Mono, D2 Serif, D2 Naskh, and the Arabic face of their watermark line);
 *   late  faces only text outside the first screen uses (Cyrillic on English pages, the other pair).
 * The layout prints each group in its own nonce'd <style data-d2-fonts="…">; the boot script (d2::shell.boot)
 * keeps "wide" (below 768 px), "docs" (unless the first screen shows sample documents) and "late" disabled until
 * the first contentful paint, so their files load after it. Without JavaScript every group stays enabled.
 */
final class FontFaces
{
    public const GROUPS = ['base', 'wide', 'docs', 'late'];

    /**
     * pair => locale => family => group, or family => [file key => group, '*' => group]. Files are the manifest keys
     * (public/fonts/d2/manifest.json); local() fallback faces are always "base"; a family not listed is "late".
     */
    private const MAP = [
        'b' => [
            'en' => [
                'D2 Sans' => ['onest-latin-wght-normal' => 'base', '*' => 'late'],
                'D2 Sans Cyrillic' => 'late',
                'D2 Sans Arabic Script' => 'docs', // the watermark's Arabic line, Arabic words (lang="ar")
                'D2 Sans Arabic' => 'docs',
                'D2 Mono' => 'docs', 'D2 Serif' => 'docs', 'D2 Naskh' => 'docs',
            ],
            'ru' => [
                'D2 Sans' => 'base',
                'D2 Sans Cyrillic' => 'base',
                'D2 Sans Arabic Script' => 'docs',
                'D2 Sans Arabic' => 'docs',
                'D2 Mono' => 'docs', 'D2 Serif' => 'docs', 'D2 Naskh' => 'docs',
            ],
            'ar' => [
                'D2 Sans Arabic' => 'base',
                'D2 Sans Arabic Script' => 'base',
                'D2 Sans' => 'late', // text marked lang="en" or lang="ru"
                'D2 Sans Cyrillic' => 'late',
                'D2 Mono' => 'docs', 'D2 Serif' => 'docs', 'D2 Naskh' => 'docs',
            ],
        ],
        'a' => [
            'en' => ['D2 Graphik' => 'base', 'D2 Graphik Cyrillic' => 'base', 'D2 Graphik Arabic Script' => 'docs', 'D2 Graphik Arabic' => 'docs', 'D2 Mono' => 'docs', 'D2 Serif' => 'docs', 'D2 Naskh' => 'docs'],
            'ru' => ['D2 Graphik' => 'base', 'D2 Graphik Cyrillic' => 'base', 'D2 Graphik Arabic Script' => 'docs', 'D2 Graphik Arabic' => 'docs', 'D2 Mono' => 'docs', 'D2 Serif' => 'docs', 'D2 Naskh' => 'docs'],
            'ar' => ['D2 Graphik Arabic' => 'base', 'D2 Graphik Arabic Script' => 'base', 'D2 Graphik' => 'late', 'D2 Graphik Cyrillic' => 'late', 'D2 Mono' => 'docs', 'D2 Serif' => 'docs', 'D2 Naskh' => 'docs'],
        ],
    ];

    /**
     * Faces of the "base" group that the first screen needs but the preloads leave out, as document.fonts.load()
     * arguments [font, sample text] the boot script starts in the head (data-d2-early), so they arrive with the
     * preloads instead of at the first layout. Pair b, Arabic pages: the Latin files of D2 Sans Arabic (every space,
     * digit and code of Arabic text) at 400 and 600, and the 500 faces (UI labels, buttons). English and Russian
     * need nothing more: Onest's variable files draw every weight. Pair a: the 500 face of the page's family.
     */
    private const EARLY_LOADS = [
        'b' => [
            'ar' => [['400 16px "D2 Sans Arabic"', 'A'], ['500 16px "D2 Sans Arabic"', 'اA'], ['600 16px "D2 Sans Arabic"', 'A']],
        ],
        'a' => [
            'en' => [['500 16px "D2 Graphik"', 'A']],
            'ru' => [['500 16px "D2 Graphik"', 'AЖ']],
            'ar' => [['500 16px "D2 Graphik Arabic"', 'اA']],
        ],
    ];

    /**
     * The faces the sample documents draw in a first screen that shows them (the home stage from 768 px, the 404's
     * misfiled file), as document.fonts.load() arguments per locale: the boot script starts them in the head
     * instead of at the first layout, so the documents, their numbers and their three-language watermark (Mono 500;
     * the Arabic line at 600: on English and Russian pages its letters come from the Arabic script alias, on Arabic
     * pages its spaces and dots from the Arabic family's Latin) are complete at the first paint.
     */
    private const DOC_LOADS = [
        'en' => [['400 16px "D2 Serif"', 'A'], ['400 16px "D2 Mono"', '0'], ['500 16px "D2 Mono"', 'AЖ'], ['600 16px "{arabic} Script"', 'ع']],
        'ru' => [['400 16px "D2 Serif"', 'AЖ'], ['400 16px "D2 Mono"', '0'], ['500 16px "D2 Mono"', 'AЖ'], ['600 16px "{arabic} Script"', 'ع']],
        'ar' => [['400 16px "D2 Naskh"', 'عA'], ['400 16px "D2 Mono"', '0'], ['500 16px "D2 Mono"', '0Ж'], ['600 16px "{arabic}"', 'A']],
    ];

    /** @var array<string, mixed> */
    private static array $memo = [];

    /** @return list<array{0: string, 1: string}> */
    public static function earlyLoads(string $locale): array
    {
        return self::EARLY_LOADS[Fonts::pair()][$locale] ?? [];
    }

    /** @return list<array{0: string, 1: string}> */
    public static function docLoads(string $locale): array
    {
        $arabic = Fonts::pair() === 'a' ? 'D2 Graphik Arabic' : 'D2 Sans Arabic';

        return array_map(
            fn (array $load) => [str_replace('{arabic}', $arabic, $load[0]), $load[1]],
            self::DOC_LOADS[$locale] ?? self::DOC_LOADS['en'],
        );
    }

    /** Every rule, minified (one block: the admin panel, the language chooser). */
    public static function css(): string
    {
        $source = self::source();

        return $source === null ? '' : self::$memo['css:'.$source['key']] ??= self::minify($source['css']);
    }

    /**
     * The rules of each group for one locale, minified: ['base' => css, 'wide' => css, 'docs' => css, 'late' => css]
     * (an empty string for an empty group). An unknown locale gets the English map.
     *
     * @return array<string, string>
     */
    public static function groups(string $locale): array
    {
        $source = self::source();
        $out = array_fill_keys(self::GROUPS, '');
        if ($source === null) {
            return $out;
        }
        $pair = Fonts::pair();
        $map = self::MAP[$pair][$locale] ?? self::MAP[$pair]['en'];

        return self::$memo['groups:'.$pair.':'.$locale.':'.$source['key']] ??= (function () use ($source, $map, $out) {
            $rules = [];
            preg_match_all('/@font-face\s*\{[^}]*\}/s', (string) preg_replace('#/\*.*?\*/#s', '', $source['css']), $m);
            foreach ($m[0] as $rule) {
                $rules[self::groupOf($rule, $map)][] = $rule;
            }
            foreach ($rules as $group => $list) {
                $out[$group] = self::minify(implode("\n", $list));
            }

            return $out;
        })();
    }

    /** @param array<string, string|array<string, string>> $map */
    private static function groupOf(string $rule, array $map): string
    {
        if (! preg_match('/url\("?\/fonts\/d2\/([a-z0-9-]+)\.[0-9a-f]+\.woff2"?\)/', $rule, $file)) {
            return 'base'; // local() fallbacks
        }
        $family = preg_match('/font-family:\s*"([^"]+)"/', $rule, $f) ? $f[1] : '';
        $entry = $map[$family] ?? 'late';
        $group = is_array($entry) ? ($entry[$file[1]] ?? $entry['*'] ?? 'base') : $entry;

        return in_array($group, self::GROUPS, true) ? $group : 'base';
    }

    /** @return array{css: string, key: string}|null */
    private static function source(): ?array
    {
        $path = resource_path('css/d2/base/fonts.css');
        if (! is_file($path)) {
            return null;
        }
        $key = $path.':'.filemtime($path);

        return self::$memo['source:'.$key] ??= ['css' => (string) file_get_contents($path), 'key' => $key];
    }

    private static function minify(string $css): string
    {
        return trim((string) preg_replace(
            ['#/\*.*?\*/#s', '/\s+/', '/\s*([{};,])\s*/', '/:\s+/'],
            ['', ' ', '$1', ':'],
            $css,
        ));
    }
}
